1803	  // Intersection Observer for reveal animations
1804	  // Use astro:page-load to work with View Transitions
1805	  function initRevealAnimations() {
1806	    const observerOptions = {
1807	      root: null,
1808	      rootMargin: '0px 0px -100px 0px',
1809	      threshold: 0.1
1810	    };
1811	
1812	    const revealObserver = new IntersectionObserver((entries) => {
1813	      entries.forEach(entry => {
1814	        if (entry.isIntersecting) {
1815	          entry.target.classList.add('visible');
1816	          revealObserver.unobserve(entry.target);
1817	        }
1818	      });
1819	    }, observerOptions);
