---
import BaseLayout from "../layouts/BaseLayout.astro";
import GreenblocksHeader from "../components/layout/GreenblocksHeader.astro";
import Footer from "../components/layout/Footer.astro";
import CookieNotice from "../components/features/CookieNotice.astro";
import {
  Leaf,
  Building2,
  Users,
  Heart,
  TreeDeciduous,
  Sparkles,
  Target,
  Handshake,
  Clock,
  ArrowRight,
  SearchCheck,
  HeartPulse,
  TrendingUp,
} from "lucide-astro";

const lang = "en";
---

<BaseLayout
  title="Greenblocks by Aunova - Community Impact Infrastructure"
  description="The foundational infrastructure layer for sustainable, healthy, and living communities. Greenblocks enables a new way of living where environmental responsibility, healthy living, and human connection are embedded into how communities function."
  lang={lang}
>
  <link slot="head" rel="preload" as="font" type="font/woff2" href="/fonts/ClashDisplay-Semibold.woff2" crossorigin />
  <link slot="head" rel="preload" as="font" type="font/woff2" href="/fonts/Satoshi-Regular.woff2" crossorigin />

  <GreenblocksHeader />

  <div class="gb-page">
    <!-- Section 1: Hero -->
    <section class="gb-hero">
      <!-- Background image -->
      <div class="gb-hero-bg">
        <img
          src="/images/greenblocks-hero.webp"
          alt="Sustainable community visualization with green architecture and people"
          class="gb-hero-bg-image"
          loading="eager"
        />
        <!-- Floating icons on the image -->
        <div class="gb-hero-icons">
          <div class="gb-hero-icon gb-hero-icon-1">
            <Leaf size={20} />
          </div>
          <div class="gb-hero-icon gb-hero-icon-2">
            <Heart size={20} />
          </div>
          <div class="gb-hero-icon gb-hero-icon-3">
            <Users size={20} />
          </div>
        </div>
      </div>

      <!-- Text overlay -->
      <div class="gb-hero-overlay">
        <div class="gb-hero-content">
          <div class="gb-hero-brand">
            <span class="gb-brand-name">Greenblocks</span>
          </div>
          <p class="gb-hero-subtitle">Community Impact Infrastructure</p>

          <h1 class="gb-hero-title">
            The foundational infrastructure layer for sustainable, healthy, and living communities
          </h1>

          <p class="gb-hero-description">
            Greenblocks is the community impact infrastructure for the built world. It enables a new way of living — where environmental responsibility, healthy living, and human connection are embedded into how communities function.
          </p>

          <a href="/en/contact" class="gb-btn gb-btn-outline">
            Begin a conversation about co-creating a community system
            <ArrowRight size={18} />
          </a>
        </div>
      </div>
    </section>

    <!-- Section 2: The Problem -->
    <section class="gb-section" id="problem">
      <div class="gb-container">
        <div class="gb-reveal">
          <h2 class="gb-heading">Modern communities are <span class="gb-warm">structurally blind</span>.</h2>

          <div class="gb-problem-grid">
            <div class="gb-problem-content">
              <p class="gb-text">
                People live in buildings, but not in communities. Daily life produces
                environmental, health, and social consequences, yet these remain largely invisible.
              </p>

              <p class="gb-text" style="margin-top: 1.5rem;">
                Cities and developments today operate <strong>without</strong> real infrastructure to:
              </p>

              <ul class="gb-check-list">
                <li><span class="gb-check">✓</span> understand their environmental impact</li>
                <li><span class="gb-check">✓</span> support healthy living by default</li>
                <li><span class="gb-check">✓</span> connect daily behavior to long-term outcomes</li>
                <li><span class="gb-check">✓</span> cultivate real community life</li>
              </ul>

              <div class="gb-problem-quote">
                <p><em>Sustainability becomes reporting.</em></p>
                <p><em>Health becomes an individual struggle.</em></p>
                <p><em>Community becomes accidental.</em></p>
              </div>

              <p class="gb-text" style="margin-top: 1.5rem;">
                These are not separate problems.<br />
                They are symptoms of the same missing system.
              </p>

              <p class="gb-text-emphasis">
                What is missing is <em>community impact infrastructure</em>.
              </p>
            </div>

            <div class="gb-problem-visual">
              <img src="/images/greenblocks-icons.webp" alt="Community impact icons" class="gb-problem-image" />
              <div class="gb-problem-grid-overlay">
                <span></span>
                <span></span>
                <span class="gb-grid-card">
                  <strong>Isolated Sustainability</strong>
                  <small>Sustainability efforts are disconnected and hard to measure.</small>
                </span>
                <span></span>
                <span></span>
                <span></span>
                <span></span>
                <span class="gb-grid-card">
                  <strong>Disconnected Health</strong>
                  <small>Healthy living is difficult without supportive environments.</small>
                </span>
                <span></span>
                <span></span>
                <span class="gb-grid-card">
